import {predictionBoundary,boundaryText,boundaryNote} from './boundaries.mjs';
import {predict,compare,batchPredict,logistic,rawScore} from './engine.mjs';
import {initRankings} from './rankings.mjs?v=nav2';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let models={},batchResult=null,batchFilename='',busy=false;
const model=()=>models[$('#year').value],notice=(message='')=>{$('#notice').textContent=message;};
const refreshRankings=initRankings(model,()=>$('#year').value);
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function openTab(id){document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-pressed',b.dataset.tab===id);});notice();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>openTab(b.dataset.tab));
$('#subjects').innerHTML=Array.from({length:6},(_,i)=>`<div class="subject-row"><label>Subject ${i+1}${i===5?' (optional)':''}<select class="subject"><option value="">Choose a subject</option></select></label><label>Raw score<input type="number" min="0" max="100" step="any" placeholder="0–100"></label></div>`).join('');
$('#compare').innerHTML=`<div class="card full"><h2>Compare equivalent results</h2><p>See how a raw score scales, then find the equivalent raw result in other subjects.</p><div class="inline"><label>Subject<select class="subject" id="compare-subject"></select></label><label>Raw score<input id="compare-raw" type="number" min="0" max="100" step="any" value="80"></label><button class="primary" id="convert">Compare subjects</button></div><p id="compare-summary" aria-live="polite"></p><div id="compare-results"></div></div>`;
$('#batch').innerHTML=`<div class="card full"><h2>Predict a cohort from Excel</h2><p>Choose an .xlsx or .xls workbook with a <strong>Data</strong> sheet. Each student needs at least five distinct subjects. Names identify students; use unique IDs in the Name column where names repeat.</p><button id="template">Download input template</button><div class="file"><label>Excel workbook<input id="workbook" type="file" accept=".xlsx,.xls"></label><p class="muted">Processed in this browser. Maximum file size: 10 MB; maximum 10,000 subject rows.</p></div><label><input id="adjust" type="checkbox"> Adjust mock external results using MEAConversions</label><p class="muted">As in the original model, adjustments use c + m × external score and cap at 50. Subjects without conversions stay unchanged and are listed in the results notice.</p><button class="primary" id="run-batch">Run predictions</button> <button id="download" hidden>Download results</button><p id="batch-status" aria-live="polite"></p><div id="batch-results"></div></div>`;
$('#curves').innerHTML=`<div class="card full"><div class="inline"><div><h2>Explore the fitted scaling curves</h2><p>Highlight a subject to see its curve and source data points.</p></div><label>Highlight subject<select class="subject" id="curve-subject"></select></label></div><div id="curve-plot"></div><p id="curve-info" class="muted"></p><p class="muted">The 2025 data is from the QTAC ATAR Report 2025. Earlier year labels follow the original filenames and have not been independently verified. Curves extrapolate between and beyond the source points. The ATAR conversion uses the original fixed approximation for every year.</p></div>`;
function clearSingle(){$('#prediction-range').textContent='';$('#atar').textContent='—';$('#aggregate').textContent='Add your subjects to calculate a prediction.';$('#single-results').innerHTML='';}
function clearBatch(){batchResult=null;$('#download').hidden=true;$('#batch-results').innerHTML='';$('#batch-status').textContent='';}
function setYear(){const names=Object.keys(model().subjects).sort();document.querySelectorAll('.subject').forEach(s=>{const current=s.value;s.innerHTML='<option value="">Choose a subject</option>'+names.map(n=>`<option>${esc(n)}</option>`).join('');s.value=names.includes(current)?current:'';});$('#curve-subject').value=names.includes('Mathematical Methods')?'Mathematical Methods':names[0];clearSingle();clearBatch();$('#compare-summary').textContent='';$('#compare-results').innerHTML='';notice();plotCurves();updateSourceNote();refreshRankings();}
function showPrediction(entries){const result=predict(model(),entries);const bounds=predictionBoundary($('#year').value,entries,result.aggregate,result.atar);$('#prediction-range').textContent=bounds.reason?bounds.reason:'Experimental comparison range: '+boundaryText(bounds)+' · '+bounds.n+' trials in this TEA band. '+boundaryNote;$('#atar').textContent=result.atar===0?'<30':result.atar.toFixed(2);$('#aggregate').textContent=`${$('#year').value} dataset · Best-five aggregate ${result.aggregate.toFixed(2)}`;$('#single-results').innerHTML=result.rows.map(r=>`<div style="margin-top:18px"><div style="display:flex;justify-content:space-between;gap:12px"><span>${esc(r.subject)}${r.counted?'':' (not counted)'}</span><strong>${r.scaled.toFixed(1)}</strong></div><div class="bar"><i style="width:${r.scaled}%"></i></div></div>`).join('');return result;}
$('#predict').onclick=()=>{clearSingle();notice();try{const entries=[];document.querySelectorAll('#subjects .subject-row').forEach(row=>{const subject=row.querySelector('select').value,raw=row.querySelector('input').value;if(subject||raw){if(!subject)throw Error('Choose a subject for every entered score.');entries.push({subject,raw:rawScore(raw)});}});showPrediction(entries);}catch(e){notice(e.message);}};
$('#single').addEventListener('input',clearSingle);$('#single').addEventListener('change',clearSingle);
$('#convert').onclick=()=>{notice();$('#compare-results').innerHTML='';$('#compare-summary').textContent='';try{const s=$('#compare-subject').value,raw=rawScore($('#compare-raw').value),r=compare(model(),s,raw);$('#compare-summary').textContent=`${s}: raw ${raw} → scaled ${r.scaled.toFixed(1)} (${$('#year').value} dataset)`;$('#compare-results').innerHTML=table(['Subject','Equivalent raw score'],r.rows.map(row=>[row.subject,row.raw===null?'Outside 0–100':row.raw.toFixed(1)]));}catch(e){notice(e.message);}};
$('#compare').addEventListener('input',()=>{$('#compare-results').innerHTML='';$('#compare-summary').textContent='';});
function plotCurves(){if(!model())return;const name=$('#curve-subject').value,c=model().subjects[name],x=v=>55+v*7,y=v=>345-v*3;let svg='<svg viewBox="0 0 800 410" role="img" aria-label="Raw versus scaled score curves"><defs><clipPath id="chart-clip"><rect x="55" y="45" width="700" height="300"/></clipPath></defs>';for(let v=0;v<=100;v+=20)svg+=`<path d="M55 ${y(v)}H755 M${x(v)} 45V345" stroke="#e4eaf1"/><text x="42" y="${y(v)+5}" text-anchor="end" fill="#567084" font-size="14">${v}</text><text x="${x(v)}" y="370" text-anchor="middle" fill="#567084" font-size="14">${v}</text>`;svg+='<g clip-path="url(#chart-clip)">';const path=curve=>Array.from({length:101},(_,raw)=>`${raw?'L':'M'}${x(raw)},${y(logistic(raw,curve.parameters))}`).join(' ');for(const curve of Object.values(model().subjects))svg+=`<path d="${path(curve)}" fill="none" stroke="#bbccd9" stroke-width="1"/>`;if(c){svg+=`<path d="${path(c)}" fill="none" stroke="#007e75" stroke-width="3"/>`;c.raw.forEach((raw,i)=>{svg+=`<circle cx="${x(raw)}" cy="${y(c.scaled[i])}" r="5" fill="#15263e"/>`;});}svg+='</g><text x="405" y="402" text-anchor="middle" fill="#526479" font-size="16">Raw score</text><text x="16" y="30" fill="#526479" font-size="16">Scaled score</text></svg>';$('#curve-plot').innerHTML=svg;$('#curve-info').textContent=c?`${name} · ${c.raw.length} source points · Fit RMSE ${c.rmse.toFixed(2)} scaled points · ${Object.keys(model().subjects).length} subjects in dataset`:'';}
$('#curve-subject').onchange=plotCurves;
function writeWorkbook(sheets,filename){const wb=XLSX.utils.book_new();for(const [name,rows]of sheets){const ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=Object.keys(rows[0]??{}).map(key=>({wch:Math.max(16,Math.min(40,key.length+6))}));XLSX.utils.book_append_sheet(wb,ws,name);}XLSX.writeFile(wb,filename);}
$('#template').onclick=()=>{try{writeWorkbook([['Data',[{Name:'',Subject:'',IA1:'',IA2:'',IA3:'',MEA:'',FIA1:'',FIA2:'',FIA3:'',FEA:''}]],['MEAConversions',[{Subject:'',m:'',c:''}]],['Subjects',Object.keys(model().subjects).sort().map(Subject=>({Subject}))],['Instructions',[{Instruction:'Enter one row per student and subject on Data. Supply at least five distinct subjects per student. Use unique IDs as Name if names repeat.'},{Instruction:'Fill IA1, IA2, IA3 and MEA, or matching fallback columns. Zero is valid. All four components are required.'},{Instruction:'Totals must be 0–100. Scores must already use their appropriate assessment weights.'},{Instruction:'MEAConversions is optional unless mock adjustment is selected. Enter Subject, m and c for subjects to adjust.'},{Instruction:`Subject list uses the ${$('#year').value} dataset.`}]]],'ATAR-input-template.xlsx');}catch(e){notice(e.message);}};
$('#workbook').onchange=clearBatch;$('#adjust').onchange=clearBatch;
$('#run-batch').onclick=async()=>{if(busy)return;notice();clearBatch();const file=$('#workbook').files[0];if(!file)return notice('Choose an Excel workbook first.');if(!/\.(xlsx|xls)$/i.test(file.name))return notice('Choose an .xlsx or .xls workbook.');if(file.size>10*1024*1024)return notice('Choose a workbook smaller than 10 MB.');busy=true;for(const id of ['run-batch','year','adjust','workbook'])$('#'+id).disabled=true;$('#batch-status').textContent='Reading and calculating on this device…';try{await new Promise(r=>setTimeout(r,20));const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellFormula:false});if(!wb.Sheets.Data)throw Error('The workbook needs a sheet named Data.');const data=XLSX.utils.sheet_to_json(wb.Sheets.Data,{defval:null});if(data.length>10000)throw Error('Please split the workbook into fewer than 10,001 subject rows.');const conversions=wb.Sheets.MEAConversions?XLSX.utils.sheet_to_json(wb.Sheets.MEAConversions,{defval:null}).filter(r=>Object.values(r).some(v=>v!==null&&String(v).trim()!=='')):null;batchResult=batchPredict(model(),data,conversions,$('#adjust').checked);for(const r of batchResult.results){const entries=batchResult.breakdown.filter(b=>b.Name===r.Name).map(b=>({subject:b.Subject,raw:b.Raw}));const bounds=predictionBoundary($('#year').value,entries,r.Aggregate,r.ATAR);r['Comparison range']=boundaryText(bounds);}batchFilename=`ATARPred-${file.name.replace(/\.[^.]+$/,'')}-${$('#year').value}.xlsx`;$('#batch-results').innerHTML=table(['Student','Best-five aggregate','Estimated ATAR','Experimental comparison range'],batchResult.results.slice(0,200).map(r=>[r.Name,r.Aggregate.toFixed(2),r.ATAR===0?'<30':r.ATAR.toFixed(2),r['Comparison range']]));$('#batch-status').textContent=`${boundaryNote} ${batchResult.results.length} students processed using ${$('#year').value}. ${batchResult.results.length>200?'Showing the first 200; the download contains everyone.':''}`;notice(batchResult.warnings.join(' '));$('#download').hidden=false;}catch(e){clearBatch();notice(e.message);}finally{busy=false;for(const id of ['run-batch','year','adjust','workbook'])$('#'+id).disabled=false;}};
$('#download').onclick=()=>{if(!batchResult)return;try{writeWorkbook([['ATAR Predictions',batchResult.results],['Subject Breakdown',batchResult.breakdown],['Model Notes',[{Note:boundaryNote},{Note:`Dataset: ${$('#year').value}; ${model().file}.`},{Note:'Original fixed aggregate-to-ATAR approximation. Estimates only; not an eligibility check. ATAR 0 represents below 30.'},{Note:`Mock adjustments selected: ${$('#adjust').checked}.`},...batchResult.warnings.map(Note=>({Note}))]]],batchFilename);}catch(e){notice(e.message);}};
const sourceNote=document.createElement('p');sourceNote.className='muted';sourceNote.id='source-note';document.querySelector('nav').after(sourceNote);
function updateSourceNote(){if(!model())return;sourceNote.innerHTML=model().source?`2025: ${Object.keys(model().subjects).length} subjects · <a href="https://qtac-files.s3.ap-southeast-2.amazonaws.com/ATAR_Report_2025.pdf" target="_blank" rel="noopener noreferrer">QTAC ATAR Report 2025</a> (February 2026), tables 6–7. Small-cohort results withheld by QTAC are unavailable. Chinese (Senior External Examination), Korean and Vietnamese use Senior External Examination data.`:'Historical dataset: '+esc(model().file)+'. Year labels follow the original app.';}
$('#year').onchange=()=>{setYear();updateSourceNote();};
try{const response=await fetch('./models.json');if(!response.ok)throw Error('Scaling data could not be loaded. Reload the page to try again.');models=(await response.json()).models;$('#year').innerHTML=Object.keys(models).sort().map(y=>`<option>${y}</option>`).join('');$('#year').value=Object.keys(models).sort().at(-1);setYear();}catch(e){notice(e.message);document.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'predict_individual_atar',title:'Predict individual ATAR',description:'Select a dataset and five or six subjects, then calculate and display an estimated ATAR. No upload.',inputSchema:{type:'object',properties:{year:{type:'string',enum:Object.keys(models)},entries:{type:'array',minItems:5,maxItems:6,items:{type:'object',properties:{subject:{type:'string'},raw:{type:'number',minimum:0,maximum:100}},required:['subject','raw'],additionalProperties:false}}},required:['year','entries'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(busy)throw Error('Wait for spreadsheet processing to finish.');if(!models[input.year]||!Array.isArray(input.entries)||input.entries.length>6)throw Error('Select an available year and five or six subjects.');const checked=predict(models[input.year],input.entries);$('#year').value=input.year;setYear();openTab('single');document.querySelectorAll('#subjects .subject-row').forEach((row,i)=>{row.querySelector('select').value=input.entries[i]?.subject??'';row.querySelector('input').value=input.entries[i]?.raw??'';});showPrediction(input.entries);return {year:input.year,aggregate:checked.aggregate,atar:checked.atar,boundary:predictionBoundary(input.year,input.entries,checked.aggregate,checked.atar)};}})).catch(()=>{});}catch{}}
